width=\"56\" height=\"96\" fill=\"#888\" stroke=\"#fff\"/%3E%3Crect x=\"17\" y=\"117\" width=\"56\" height=\"96\" fill=\"#888\" stroke=\"#fff\"/%3E%3Crect x=\"17\" y=\"216\" width=\"56\" height=\"98\" fill=\"#888\" stroke=\"#fff\"/%3E%3Crect x=\"220\" y=\"15\" width=\"26\" height=\"54\" fill=\"#8a6a40\"/%3E%3Crect x=\"216\" y=\"72\" width=\"30\" height=\"60\" fill=\"#888\" stroke=\"#fff\"/%3E%3Cpath d=\"M150 332 v62 M150 332 A62 62 0 0 1 212 394\" fill=\"none\" stroke=\"#333\"/%3E%3Cline x1=\"212\" y1=\"332\" x2=\"212\" y2=\"394\" stroke=\"#333\"/%3E%3C/svg%3E","prepared":{"role":"Зертханаға меңгерушісі","name":"Баймукашев Р.С."},"agreed":{"role":"Кафедра меңгерушісі","name":"Мұқаш Жанар"},"source":"CV Lab passport (docx), uploaded 2026-11-11"}$j$::jsonb as doc) d
 where l.slug = 'computer-vision'
on conflict (lab_id, year) do update set doc = excluded.doc, official_name = coalesce(lp.official_name, excluded.official_name),
  room = coalesce(lp.room, excluded.room), head = coalesce(lp.head, excluded.head)
 where lp.doc is null;

